insert into public.assessment_cycles (id, name, cycle_year, iat_version, status, period_from, period_to, notes)
insert into public.responses (id, cycle_id, indicator_id, is_na, na_justification, gap_remarks, recommended_action, status) values
('c17b15c8-b808-595b-a5e3-b86125a7db6f'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A1.1', false, null, 'No ordinance establishing the CDRRMO as a regular department with JMC 2014-1 divisions; the EO is the only basis. (Field FGD notes formerly typed here were moved to A2.4, A2.6, A2.10 and B6.1.)', 'Draft an ordinance creating the CDRRMO as a regular department with Admin & Training, Research & Planning and Operations & Warning divisions and their functions (RA 10121 Sec. 12(c); JMC 2014-1). Attach the organogram and staffing pattern from MOO Ch.2.', 'provisional'),
('012a93b7-515f-579e-b82d-b686e69e176d'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A1.2', false, null, 'Composition incomplete against RA 10121 Sec. 11 (incl. CSO and private-sector seats). (Operations FGD notes formerly here were moved to B6.1 and B7.1.)', 'Issue an updated EO on CDRRMC composition listing every RA 10121 Sec. 11 seat by office, with at least 4 accredited CSOs and a private-sector seat (e.g., EDC). Record the roster as an MOO Ch.1 annex and review it yearly.', 'provisional'),
('283b7870-a4bb-57b5-b913-ba65abab616f'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A1.3', false, null, '[Workbook score 4; imported as 3 because no test, exercise or after-action review is on record (a 4 needs one). Restore it once the evidence is attached.] Validate with the last 4 quarters of minutes and attendance. (Admin FGD notes formerly here were moved to A2.4, A2.6 and A2.10.)', 'Keep the quarterly schedule; add a standing agenda item on RA 12287 readiness and the action plan from this assessment. Use the minutes template in MOO Ch.1.', 'provisional'),
('33dca86b-ac84-535f-a6f3-585766be3912'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A1.4', false, null, '[Workbook score 4; imported as 2 because it rests on FGD self-scoring only (interviews and FGDs cannot support more than 2). Restore it once the evidence is attached.] Validate: secretariat SOP and agenda/minutes templates to be sighted in the workshop.', 'Write the secretariat procedure (notice, agenda, quorum, minutes, resolutions, tracking) into MOO Ch.2.', 'provisional'),
('b9af8f93-7828-5b7d-bf4d-9e3d2760f414'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A1.5', false, null, 'Evacuation ordinance lacks procedural steps (who orders, triggers, enforcement); class-suspension rules not barangay-specific; ZO has no hazard overlay zones.', 'Amend the evacuation ordinance to add procedural statements: triggers tied to the warning-action matrix (A6.2), authority to order, assistance to PWD/elderly, livestock and pets (RA 12287 IRR Rule IV), and enforcement. Add granular (barangay/school-level) class and work suspension. In the CLUP/ZO update, add flood, landslide, storm-surge, liquefaction and tsunami overlay zones (CDRA MDA 1).', 'provisional'),
('5b1a42b2-d11d-535f-a8e9-c0aa9e59b0c0'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A1.6', false, null, 'Assessor adjustment 4 -> 3: past use is shown, but no stand-alone written protocol and no test/AAR showing improvement were cited, which a 4 requires. v1.1 limits this item to State of Calamity; the State of Imminent Disaster is now A1.8.', 'Write a State of Calamity protocol in MOO Ch.1: criteria (NDRRMC Memo on SoC criteria), RDANA/PDNA basis, CDRRMC recommendation, SP resolution template, post-declaration measures (price freeze, QRF use, reporting). Add a note on how to read national/regional declarations that affect Ormoc.', 'provisional'),
('1d9cddd8-8636-5604-afde-e262e4c2b76d'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A1.7', false, null, '[Workbook score 4; imported as 2 because it rests on FGD self-scoring only (interviews and FGDs cannot support more than 2). Restore it once the evidence is attached.] Validate with CDC/LFC minutes.', 'Keep representation; use the LFC seat to secure the AA line (A4.6) and the EOC budget (B7.5) in the FY2028 budget call.', 'provisional'),
('6e0cc231-acc4-5131-b65b-41df583596eb'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A1.8', false, null, 'Mandatory new requirement not yet in place: request to RDRRMC VIII (24-h reply), Mayor''s EO, adoption rule, lifting grounds.', 'Draft the State of Imminent Disaster procedure (IRR Rule II Sec. 6; Rule III Secs. 2-4): PDRA trigger, CDRRMC resolution, request to RDRRMC VIII, Mayor''s EO template, adoption rule, lifting and the 45-day report (A10.8). Confirm with OCD VIII whether a Provincial declaration applies to an ICC. Walk it through in a tabletop to reach score 3.', 'provisional'),
('2156dae5-216b-53a3-9128-b76554891d9b'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A2.1', false, null, 'Divisions exist as sections, but not as an approved JMC 2014-1 structure; normal-operations tasks and response tasks are mixed (Planning FGD).', 'Adopt the JMC 2014-1 organogram (Head + 3 divisions) with separate normal-operations and response (EOC) roles, through the ordinance in A1.1 and MOO Ch.2.', 'provisional'),
('7981b083-b30f-519a-9a28-04f3cbab2ee4'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A2.2', false, null, '[Workbook score 4; imported as 3 because no test, exercise or after-action review is on record (a 4 needs one). Restore it once the evidence is attached.] Validate appointment papers vs CSC QS.', 'Maintain; document succession (OIC order of precedence) in MOO Ch.2.', 'provisional'),
('4614955e-cace-5e8f-9e3c-dcb79cb1e1f9'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A2.3', false, null, 'Assessor adjustment 4 -> 2 under the conflicting-evidence rule (take the lower). Restore if the current Plantilla of Personnel shows all JMC 2014-1 minimum positions filled.', 'Get the Plantilla of Personnel and vacancy list; compute filled/required. Request creation and funding of the 10 planned items in the FY2028 budget, prioritising Operations & Warning (24/7 OpCen) and Research & Planning (GIS).', 'provisional'),
('732a471b-7b05-5894-ae14-1cc993d8713f'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A2.4', false, null, 'JDs not defined per position; Admin functions bypassed in some activities.', 'Write position descriptions for every CDRRMO and EOC role (MOO annex), aligned to RA 10121 functions; link them to IPCR/OPCR targets.', 'provisional'),
('ab53dfc9-1973-50e5-87dc-c8d208d32bb6'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A2.5', false, null, '24/7 operation exists in practice but no approved normal-operations (White) SOP and roster.', 'Write the OpCen normal-operations SOP (shifts, handover, monitoring, logbook, reporting times 6AM/6PM per RDRRMC8 Res. 12-006) as EOC Manual Ch.4/Ch.5, using the RDRRMOC SOPG 2022 forms (turn-over document, swapping form, duty composition by alert level); have it approved and keep 3 months of rosters as proof of use.', 'provisional'),
('9bf9db95-0edb-5da0-8eef-d3e3d892003b'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A2.6', false, null, 'No TNA or competency-based training plan.', 'Run a TNA for all CDRRMO/EOC staff against the competency list (ICS, BLS/SFA, WASAR, CSSR, EOC, PDNA, GIS); produce a 3-year training plan with OCD VIII courses in MOO Ch.6.', 'provisional'),
('694e80ca-fd79-5b7a-8168-b48c0fc42f56'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A2.7', false, null, 'No insurance, hazard pay, PPE or MHPSS programme documented for responders.', 'Adopt a responder welfare policy: group accident insurance (staff and accredited volunteers), PPE issue list, rest cycles, MHPSS referral with CHO (RA 11036). Memo 131 also requires EOC personnel welfare.', 'provisional'),
('4ea14592-7a60-5788-adad-55ccc1d630c5'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A2.8', false, null, 'Validate: registry and accreditation records. ACDV mobilisation for AA (IRR Rule IV Sec. 5) not yet covered.', 'Formalise the ACDV registry with accreditation, insurance and deployment rules, and add AA tasks for ACDVs.', 'provisional'),
('2a1edad2-9fd7-57eb-a34e-0df53d86c11b'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A2.9', false, null, 'New mandatory item (IRR Rule IV Sec. 1; Rule VII).', 'Designate an AA focal person by office order and enrol them, BDRRMC officers, ACDVs and partner CSOs in AA training when OCD VIII cascades the IRR.', 'provisional'),
('d198a40b-8c44-51e5-83ea-50becadd0f7a'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A2.10', false, null, 'No skills inventory across CDRRMO, partner offices and barangays.', 'Build a skills inventory (SAR, engineering, logistics, GIS, PDNA, MHPSS) covering CDRRMO, CDRRMC offices and BDRRMCs; update it every 12 months (UNDRR DRSC 6.1.1).', 'provisional'),
('a3561a08-069e-5542-9ffd-0d7ca99b62e6'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A3.1', false, null, '[Workbook score 4; imported as 3 because no test, exercise or after-action review is on record (a 4 needs one). Restore it once the evidence is attached.] Validate the alignment table to NDRRMP 2020-2030 and Sendai. Barangay count in the plan (110) predates the 2022 merger; use 85.', 'Maintain; in the next update correct the barangay count to 85 and add RA 12287 anticipatory action PPAs.', 'provisional'),
('4802802d-6669-51ed-a1ae-51b54830b004'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A3.2', false, null, 'Assessor adjustment 3 -> 2 (conflicting evidence, take the lower): CDRA results are not yet carried into zoning overlays, a project screening step (C1.2) or the CDP/AIP. Restore to 3 when the updated CLUP/ZO is approved with CDRA overlays.', 'Use the CLUP/ZO update to adopt CDRA hazard overlays and the MDA 1-8 interventions; tag CDP/AIP and LCCAP projects to CDRA risk-register entries; review mainstreaming in CDP, CLUP, ELA and LCCAP (see C1.1-C1.4).', 'provisional'),
('4e61821a-2091-527b-9fc9-a1999f4a6b6d'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A3.3', false, null, 'No CPs for other top hazards (landslide, tsunami, tropical cyclone, geothermal/industrial); untested CPs.', 'Prepare CPs for the remaining priority hazards and test each by tabletop; add AA annexes (A8.8) and pre-disaster recovery annex (A9.5).', 'provisional'),
('80aca07c-2c0a-5c9b-8852-391f75e17315'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A3.4', false, null, 'PSCP not completed; no BIA or essential-functions list sighted.', 'Complete the PSCP using the PSCP Guidebook: essential functions, BIA, alternate site (links to B2.7), orders of succession, vital records. Exercise it once.', 'provisional'),
('62050213-3f6c-5c1b-ad96-ffc96cb10a76'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A3.5', false, null, '[Workbook score 4; imported as 3 because no test, exercise or after-action review is on record (a 4 needs one). Restore it once the evidence is attached.] Validate the CDRRMC resolution and link to LDRRMP PPAs.', 'Maintain; add the AA line (A4.6) and EOC operations line (B7.5) explicitly.', 'provisional'),
('32ad7cea-17c7-50c7-b639-631673e3aba0'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A3.6', false, null, 'Routes, maps and safe zones not aligned with SOPs; pre-emptive evacuation triggers per barangay missing.', 'Produce barangay evacuation maps (routes, safe zones, ECs) for all 85 barangays, starting with the 46 critical flood barangays, and link triggers to the warning-action matrix (A6.2).', 'provisional'),
('e327b421-ea9c-5038-9f7f-9357f6b96c0f'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A3.7', false, null, '[Workbook score 4; imported as 2 because it rests on FGD self-scoring only (interviews and FGDs cannot support more than 2). Restore it once the evidence is attached.] Validate the consolidated BDRRMP status matrix for 85 barangays.', 'Maintain; add AA and evacuation-map status columns to the matrix.', 'provisional'),
('e1800441-4564-5a86-9813-92c3d72de086'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A4.1', false, null, '[Workbook score 4; imported as 2 because it rests on FGD self-scoring only (interviews and FGDs cannot support more than 2). Restore it once the evidence is attached.] Validate the LDRRMF computation (5% of estimated regular revenue).', 'Maintain; keep the computation sheet with the budget.', 'provisional'),
('51b90def-3147-54ab-a71a-97b0e033d117'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A4.2', false, null, '[Workbook score 4; imported as 2 because it rests on FGD self-scoring only (interviews and FGDs cannot support more than 2). Restore it once the evidence is attached.] Validate the appropriation ordinance.', 'Maintain the 70/30 split; show the AA sub-allocation inside the 70% (A4.6).', 'provisional'),
('cbee3855-118c-52f2-8301-83cd669c6703'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A4.3', false, null, '[Workbook score 4; imported as 2 because it rests on FGD self-scoring only (interviews and FGDs cannot support more than 2). Restore it once the evidence is attached.] Validate the STF ledger and 5-year use.', 'Maintain; list STF balances as an AA fund source (A4.6).', 'provisional'),
('2e056aca-2637-522c-91b6-069aa6e1a801'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A4.4', false, null, 'Utilisation below target.', 'Track LDRRMF utilisation quarterly in the CDRRMC meeting; flag PPAs at risk by Q3.', 'provisional'),
('97831d29-05c4-5bf1-b4d4-23c058cc124c'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A4.5', false, null, '[Workbook score 3; imported as 2 because it rests on FGD self-scoring only (interviews and FGDs cannot support more than 2). Restore it once the evidence is attached.] Supplier list not refreshed; framework agreements to be confirmed.', 'Keep a pre-qualified supplier list updated each year; set framework agreements for relief goods, fuel and heavy equipment under RA 12009 IRR, usable for AA (B6.6).', 'provisional'),
('88c9dbde-603a-5b23-a4cd-4882ef0fb4e6'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A4.6', false, null, 'No AA line, no disbursement guidance.', 'Put an AA line (up to 10% of the 70% LDRRMF) in the FY2028 LDRRMFIP; map other sources (STF, donations, ODA); write Budget/Accounting/BAC steps for immediate disbursement with the 30%/70% tranche rule. Revisit when DBM-COA guidelines issue.', 'provisional'),
('7114b994-82b1-5ed5-9135-499924a1cbc2'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A4.7', false, null, 'Validate GSIS coverage of public assets and PSF proposals; CDRA shows low insurance coverage of critical facilities and none for lifelines.', 'Check that the EOC, ECs and city-owned critical facilities are on the GSIS indemnity schedule; use the CDRA facility list to set coverage priorities.', 'provisional'),
('48303372-fc90-5312-bfc4-00985b4b0432'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A4.8', false, null, '[Workbook score 3; imported as 2 because it rests on FGD self-scoring only (interviews and FGDs cannot support more than 2). Restore it once the evidence is attached.] Confirm the latest COA AAR has no unaddressed LDRRMF findings.', 'Set an internal audit check of LDRRMF before year-end.', 'provisional'),
('bb946818-cda4-5a4a-9f8e-71e90ad31286'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A4.9', false, null, 'Provisional desk score: asset-damage figures exist, but the cost of responding to the most severe credible event has not been set against the QRF, STF and other sources. Confirm with the City Budget Office.', 'Cost response and early recovery (relief, evacuation, debris, emergency repair) for a Thelma-type flash flood and a Yolanda-type typhoon from the flood and TC CPs; compare with the current QRF, STF balances and NDRRM Fund access; record the shortfall and fallback sources in the LDRRMFIP.', 'provisional'),
('cc6fb7f3-7e53-51af-9daa-122c2e3b7c51'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A5.1', false, null, 'Barangay-scale coverage to validate.', 'Maintain; publish barangay hazard maps through the shared source (A5.7).', 'provisional'),
('3c7cd8e5-365c-5250-9266-88d8a9d27ab6'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A5.2', false, null, 'No earthquake, liquefaction or tsunami DRA; climate-projection tables still labelled ''Municipality of Naval, Province of Biliran'' (template error); SP adoption and use in plans to validate.', 'Add earthquake, liquefaction and tsunami DRA; correct the Naval/Biliran table labels; adopt the CDRA with the CLUP update and set its update cycle (A5.9); cover exposure of critical facilities (A5.8) and non-asset losses (C1.3).', 'provisional'),
('b6edfcf0-4785-5e40-8976-9d9c773a5f75'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A5.3', false, null, '[Workbook score 4; imported as 3 because no test, exercise or after-action review is on record (a 4 needs one). Restore it once the evidence is attached.] Conflict to validate: 4 needs a current database used in a test or event; the plan says CBMS needs updating.', 'Validate CBMS currency; use it as the AA targeting list (A8.9).', 'provisional'),
('8d1f9242-bfc9-503c-bace-1db8fed66a1f'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A5.4', false, null, 'Event records exist in reports but there is no database.', 'Set up a disaster event and loss database (Sendai/DesInventar fields) and back-load past RDANA/PDNA data.', 'provisional'),
('5c7b7506-5971-5c59-b98a-efe991fb3c1e'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A5.5', false, null, 'No DPO designation, DSA or privacy notice sighted for DRRM data.', 'Confirm the City DPO; sign data-sharing agreements with CSWDO/CPDO for beneficiary data; add privacy notices to registration forms.', 'provisional'),
('96b50559-910e-5edd-a199-8c843d7301eb'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A5.6', false, null, 'GIS capacity in R&P not confirmed.', 'Confirm GIS staff and software; train at least 2 R&P staff.', 'provisional'),
('9b7cbbe7-21a3-5dd7-890b-0d9a341be165'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A5.7', false, null, 'No single shared source for CDRRMC offices; no public summary.', 'Set up one shared repository (hazard maps, plans, contacts, readiness summary) for CDRRMC offices and post a public summary, respecting RA 10173.', 'provisional'),
('d71978c1-2eae-55bb-a515-c82b97f19439'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A5.8', false, null, 'A facility and lifeline list exists, but dependencies and failure chains are not mapped and are not used to set protection and restoration priorities.', 'Start from the CDRA facility and lifeline tables; map dependencies among power, water, telecom, roads, hospitals, ECs and the EOC (CDRA MDA 2 items 1, 5, 6); use CREST systems-mapping to draw failure chains and set restoration priorities.', 'provisional'),
('2b9e564b-b2b7-5759-a5a3-bfe6c66b5e39'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A5.9', false, null, 'No agreed update cycle.', 'Adopt an update cycle in MOO Ch.7: hazard data <=3 years; exposure, vulnerability and critical facilities <=18 months.', 'provisional'),
('2137e00a-8b2c-5fa2-919c-6564fa36fbb9'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A6.1', false, null, 'Tech-based gauges/sensors need re-establishing (Anilao/Malbasag).', 'Restore and insure the flood/rain gauges; set a monthly functionality check; write an EWS SOP (planned PPA).', 'provisional'),
('9ac83d4c-1e6f-57da-bce8-845b46b7796e'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A6.2', false, null, 'Matrix does not yet link alert levels to SID request and AA (RA 12287).', 'Write the warning-action matrix (PAGASA/PHIVOLCS levels -> pre-emptive evacuation, class/work suspension, EOC level, SID request), built to take NDRRMC impact-based triggers when issued.', 'provisional'),
('c424131b-905b-5764-abbf-bffcd8ee9b51'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A6.3', false, null, 'No tested fallback channel when mobile networks fail.', 'Revise the dissemination SOP with non-telecom fallbacks (VHF, sirens, criers) and test to purok level twice a year with logs.', 'provisional'),
('61f516ba-eb61-53af-9c38-049a8118cf9f'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A6.4', false, null, '[Workbook score 4; imported as 2 because it rests on FGD self-scoring only (interviews and FGDs cannot support more than 2). Restore it once the evidence is attached.] Validate sample advisories in Cebuano and accessible formats.', 'Maintain; add PWD-inclusive EWS (planned PPA).', 'provisional'),
('37a945ad-cb5c-5880-9c28-fa9e629ec523'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A6.5', false, null, 'No approved risk communication plan.', 'Designate the PIO and write the risk communication plan, including rumour management.', 'provisional'),
('039cebf9-ca81-562c-bc51-63b4df29e11e'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A6.6', false, null, '[Workbook score 3; imported as 2 because it rests on FGD self-scoring only (interviews and FGDs cannot support more than 2). Restore it once the evidence is attached.] Reach targets to validate.', 'Set annual reach targets per barangay and report them.', 'provisional'),
('1b360c72-518e-5396-bd44-bc9dabbaed12'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A6.7', false, null, 'New mandatory item (IRR Rule IV Sec. 2).', 'Prepare SID public notice templates and sector-specific advisories with channels to isolated barangays.', 'provisional'),
('8764eaf9-2d56-5349-a02a-013cd9cf9968'::uuid, '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid, 'A7.1', false, null, '[Workbook score 3; imported as 2 because it rests on FGD self-scoring only (interviews and FGDs cannot support more than 2). Restore it once the evidence is attached.] Validate the training calendar and attendance.', 'Maintain; merge with the TNA plan (A2.6).', 'provisional'),
